// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<p data-line=\"0\" class=\"code-line\">When I ported routes from NestJS to Hono + Zod, rewriting DTO types into Zod schemas alone did not preserve input meaning.</p>\n<p data-line=\"2\" class=\"code-line\">In the source stack, class-transformer's <code>@Transform()</code> handled string-to-number conversion, defaults, empty-string normalization — and also boolean coercion, string trim, and wrapping single values into arrays. None of that appears in TypeScript types or class-validator constraints.</p>\n<p data-line=\"4\" class=\"code-line\">So I checked value conversion written in NestJS DTOs field by field and ported them into Zod schemas. Among those, I extracted numeric conversion repeated across projects into Zod helpers in <code>@rdlabo/workers-hono-kit</code>.</p>\n<p data-line=\"6\" class=\"code-line\">This article focuses on what values become after passing through Zod schemas.</p>\n<h2 id=\"port-value-conversion%2C-not-types\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#port-value-conversion%2C-not-types\" aria-hidden=\"true\"></a> Port value conversion, not types</h2>\n<p data-line=\"10\" class=\"code-line\">TypeScript types, validation, and value conversion are separate roles.</p>\n<h2 id=\"typescript-types-do-not-change-values-at-runtime\" data-line=\"12\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#typescript-types-do-not-change-values-at-runtime\" aria-hidden=\"true\"></a> TypeScript types do not change values at runtime</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"14\"><span class=\"line\"><span style=\"color:#F97583\">type</span><span style=\"color:#B392F0\"> Query</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  page</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> number</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">};</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"20\" class=\"code-line\">This <code>number</code> is compile-time information. If the URL is <code>?page=2</code>, path and query parameters arrive as the string <code>\"2\"</code>.</p>\n<p data-line=\"22\" class=\"code-line\">Hono's official examples also coerce string query values to number in validators when needed.</p>\n<p data-line=\"24\" class=\"code-line\"><a href=\"https://hono.dev/docs/guides/rpc#path-parameters\" rel=\"noopener noreferrer\" target=\"_blank\">https://hono.dev/docs/guides/rpc#path-parameters</a><a href=\"https://hono.dev/docs/guides/rpc#path-parameters\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://hono.dev/docs/guides/rpc#path-parameters</a></p>\n<h2 id=\"nestjs-used-%40transform()-for-shaping\" data-line=\"26\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#nestjs-used-%40transform()-for-shaping\" aria-hidden=\"true\"></a> NestJS used <code>@Transform()</code> for shaping</h2>\n<p data-line=\"28\" class=\"code-line\">In my project, fields I wanted as numbers had explicit <code>@Transform()</code>:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"30\"><span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ListQuery</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  @</span><span style=\"color:#B392F0\">Transform</span><span style=\"color:#E1E4E8\">(toNumber)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  @</span><span style=\"color:#B392F0\">IsInt</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  @</span><span style=\"color:#B392F0\">Min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  page</span><span style=\"color:#F97583\">!:</span><span style=\"color:#79B8FF\"> number</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"39\" class=\"code-line\">Each piece has a separate role:</p>\n<table data-line=\"41\" class=\"code-line\">\n<thead data-line=\"41\" class=\"code-line\">\n<tr data-line=\"41\" class=\"code-line\">\n<th>Annotation</th>\n<th>Role</th>\n</tr>\n</thead>\n<tbody data-line=\"43\" class=\"code-line\">\n<tr data-line=\"43\" class=\"code-line\">\n<td><code>page!: number</code></td>\n<td>TypeScript type</td>\n</tr>\n<tr data-line=\"44\" class=\"code-line\">\n<td><code>@Transform(toNumber)</code></td>\n<td>Shape input at runtime</td>\n</tr>\n<tr data-line=\"45\" class=\"code-line\">\n<td><code>@IsInt()</code> / <code>@Min(1)</code></td>\n<td>Validate after shaping</td>\n</tr>\n</tbody>\n</table>\n<p data-line=\"47\" class=\"code-line\">Mechanically migrating to Hono + Zod like this rejects the string <code>\"1\"</code>:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"49\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> listQuery</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  page: z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"55\" class=\"code-line\">What I needed was not only Zod numeric constraints but porting the preprocessing <code>@Transform(toNumber)</code> did.</p>\n<h2 id=\"first-ask-whether-standard-zod-is-enough\" data-line=\"57\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#first-ask-whether-standard-zod-is-enough\" aria-hidden=\"true\"></a> First ask whether standard Zod is enough</h2>\n<p data-line=\"59\" class=\"code-line\">Hono path and query parameters arrive as strings. For new APIs, <code>z.coerce.number()</code> is often enough:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"61\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> listQuery</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  page: z.coerce.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"67\" class=\"code-line\">But <code>z.coerce.number()</code> uses JavaScript <code>Number()</code>, so empty string and whitespace-only strings become <code>0</code>:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"69\"><span class=\"line\"><span style=\"color:#B392F0\">Number</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">);    </span><span style=\"color:#a0aab5\">// 0</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">Number</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'   '</span><span style=\"color:#E1E4E8\">); </span><span style=\"color:#a0aab5\">// 0</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"74\" class=\"code-line\">In schemas that allow <code>0</code>, values I wanted as missing or mistaken input pass through.</p>\n<h2 id=\"for-required-string-input%2C-pipe()-is-enough\" data-line=\"76\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#for-required-string-input%2C-pipe()-is-enough\" aria-hidden=\"true\"></a> For required string input, <code>pipe()</code> is enough</h2>\n<p data-line=\"78\" class=\"code-line\">Standard Zod escape: validate as string first, then pass to <code>z.coerce.number()</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"80\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> queryNumber</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  .</span><span style=\"color:#B392F0\">string</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  .</span><span style=\"color:#B392F0\">trim</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  .</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  .</span><span style=\"color:#B392F0\">pipe</span><span style=\"color:#E1E4E8\">(z.coerce.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">));</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">queryNumber.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'42'</span><span style=\"color:#E1E4E8\">);                   </span><span style=\"color:#a0aab5\">// 42</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">queryNumber.</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">).success;         </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">queryNumber.</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'   '</span><span style=\"color:#E1E4E8\">).success;      </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">queryNumber.</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">null</span><span style=\"color:#E1E4E8\">).success;       </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"93\" class=\"code-line\"><code>z.string()</code> limits the source; <code>trim().min(1)</code> drops empty and whitespace before numeric conversion. For new required query or path parameters, this is enough.</p>\n<p data-line=\"95\" class=\"code-line\"><a href=\"https://zod.dev/api#pipes\" rel=\"noopener noreferrer\" target=\"_blank\">https://zod.dev/api#pipes</a><a href=\"https://zod.dev/api#pipes\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://zod.dev/api#pipes</a></p>\n<h2 id=\"existing-contracts-needed-preprocessing-for-empty-values\" data-line=\"97\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#existing-contracts-needed-preprocessing-for-empty-values\" aria-hidden=\"true\"></a> Existing contracts needed preprocessing for empty values</h2>\n<p data-line=\"99\" class=\"code-line\">Source DTOs mixed fields like:</p>\n<ul data-line=\"101\" class=\"code-line\">\n<li data-line=\"101\" class=\"code-line\">Required numbers treating empty string as invalid</li>\n<li data-line=\"102\" class=\"code-line\">Numbers defaulting when the parameter is absent</li>\n<li data-line=\"103\" class=\"code-line\">Optional numbers treating empty string as unspecified</li>\n<li data-line=\"104\" class=\"code-line\">Nullable numbers keeping JSON <code>null</code> as a value</li>\n</ul>\n<p data-line=\"106\" class=\"code-line\"><code>.default()</code> and <code>.optional()</code> handle <code>undefined</code> but do not turn empty string into default or <code>undefined</code>. Rather than reimplementing each route with <code>z.preprocess()</code>, I split into four helpers.</p>\n<h2 id=\"introducing-the-shared-library\" data-line=\"108\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#introducing-the-shared-library\" aria-hidden=\"true\"></a> Introducing the shared library</h2>\n<p data-line=\"110\" class=\"code-line\">Four numeric helpers used across projects with the same contract import from <code>@rdlabo/workers-hono-kit</code> package root:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"112\"><span class=\"line\"><span style=\"color:#B392F0\">npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @rdlabo/workers-hono-kit</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"116\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNum,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNumNullable,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNumOptional,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNumWithDefault,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@rdlabo/workers-hono-kit'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"125\" class=\"code-line\"><a href=\"https://github.com/rdlabo-dev/workers-hono-kit/blob/main/src/middleware/zod-coerce.ts\" rel=\"noopener noreferrer\" target=\"_blank\">https://github.com/rdlabo-dev/workers-hono-kit/blob/main/src/middleware/zod-coerce.ts</a><a href=\"https://github.com/rdlabo-dev/workers-hono-kit/blob/main/src/middleware/zod-coerce.ts\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/rdlabo-dev/workers-hono-kit/blob/main/src/middleware/zod-coerce.ts</a></p>\n<p data-line=\"127\" class=\"code-line\"><a href=\"https://www.npmjs.com/package/@rdlabo/workers-hono-kit\" rel=\"noopener noreferrer\" target=\"_blank\">https://www.npmjs.com/package/@rdlabo/workers-hono-kit</a><a href=\"https://www.npmjs.com/package/@rdlabo/workers-hono-kit\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.npmjs.com/package/@rdlabo/workers-hono-kit</a></p>\n<p data-line=\"129\" class=\"code-line\">These are not helpers to replace every numeric field uniformly. For new required query/path, first consider <code>z.string().trim().min(1).pipe(z.coerce.number())</code>. When migrating from NestJS, check the source DTO's <code>@Transform()</code> and use only the helper matching actual empty-value handling for that field.</p>\n<h2 id=\"decide-coercion-per-field%2C-not-uniformly\" data-line=\"131\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#decide-coercion-per-field%2C-not-uniformly\" aria-hidden=\"true\"></a> Decide coercion per field, not uniformly</h2>\n<p data-line=\"133\" class=\"code-line\">I cannot migrate by coercing every field that looks numeric.</p>\n<h2 id=\"fields-that-had-%40transform()\" data-line=\"135\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#fields-that-had-%40transform()\" aria-hidden=\"true\"></a> Fields that had <code>@Transform()</code></h2>\n<p data-line=\"137\" class=\"code-line\">Fields that converted strings to numbers in the source get the same conversion on Hono + Zod:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"139\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> listQuery</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  page: </span><span style=\"color:#B392F0\">zNum</span><span style=\"color:#E1E4E8\">(z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">)),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"145\" class=\"code-line\"><code>\"1\"</code> becomes <code>1</code>, then <code>int()</code> and <code>min(1)</code> validate.</p>\n<h2 id=\"fields-without-%40transform()\" data-line=\"147\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#fields-without-%40transform()\" aria-hidden=\"true\"></a> Fields without <code>@Transform()</code></h2>\n<p data-line=\"149\" class=\"code-line\">Conversely, do not add coercion to fields that had only <code>@IsInt()</code> without <code>@Transform()</code>:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"151\"><span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> Body</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  @</span><span style=\"color:#B392F0\">IsInt</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  quantity</span><span style=\"color:#F97583\">!:</span><span style=\"color:#79B8FF\"> number</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"158\" class=\"code-line\">If this field required a number in JSON body, Zod also uses plain <code>z.number()</code>:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"160\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> body</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  quantity: z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"166\" class=\"code-line\">Using <code>zNum()</code> here might accept string <code>\"1\"</code> or <code>null</code> as numbers when they were rejected before. Migration unit is per-DTO-field conversion rules, not TypeScript <code>number</code>.</p>\n<table data-line=\"168\" class=\"code-line\">\n<thead data-line=\"168\" class=\"code-line\">\n<tr data-line=\"168\" class=\"code-line\">\n<th>NestJS DTO</th>\n<th>Hono + Zod</th>\n</tr>\n</thead>\n<tbody data-line=\"170\" class=\"code-line\">\n<tr data-line=\"170\" class=\"code-line\">\n<td><code>@Transform(toNumber)</code> + <code>@IsInt()</code></td>\n<td><code>zNum(z.number().int())</code></td>\n</tr>\n<tr data-line=\"171\" class=\"code-line\">\n<td><code>@Transform(toNumberWithDefault(20))</code></td>\n<td><code>zNumWithDefault(20, ...)</code></td>\n</tr>\n<tr data-line=\"172\" class=\"code-line\">\n<td><code>@Transform(toOptionalNumber)</code></td>\n<td><code>zNumOptional(...)</code></td>\n</tr>\n<tr data-line=\"173\" class=\"code-line\">\n<td><code>@IsInt()</code> without <code>@Transform</code></td>\n<td><code>z.number().int()</code></td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"four-numeric-helpers\" data-line=\"175\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#four-numeric-helpers\" aria-hidden=\"true\"></a> Four numeric helpers</h2>\n<h2 id=\"required%3A-znum()\" data-line=\"177\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#required%3A-znum()\" aria-hidden=\"true\"></a> required: <code>zNum()</code></h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"179\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#B392F0\"> isBlankString</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> unknown</span><span style=\"color:#E1E4E8\">)</span><span style=\"color:#F97583\">:</span><span style=\"color:#FFAB70\"> value</span><span style=\"color:#F97583\"> is</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#F97583\"> =&gt;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  typeof</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'string'</span><span style=\"color:#F97583\"> &amp;&amp;</span><span style=\"color:#E1E4E8\"> value.</span><span style=\"color:#B392F0\">trim</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#B392F0\"> rawToNumber</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> unknown</span><span style=\"color:#E1E4E8\">)</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> unknown</span><span style=\"color:#F97583\"> =&gt;</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  isBlankString</span><span style=\"color:#E1E4E8\">(value) </span><span style=\"color:#F97583\">?</span><span style=\"color:#E1E4E8\"> Number.NaN </span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Number</span><span style=\"color:#E1E4E8\">(value);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> const</span><span style=\"color:#B392F0\"> zNum</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#FFAB70\">inner</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> z</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">ZodNumber</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">()) </span><span style=\"color:#F97583\">=&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  z.</span><span style=\"color:#B392F0\">preprocess</span><span style=\"color:#E1E4E8\">(rawToNumber, inner);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"190\" class=\"code-line\">Converts numeric strings to number. Empty and whitespace-only strings become <code>NaN</code> and fail at <code>z.number()</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"192\"><span class=\"line\"><span style=\"color:#B392F0\">zNum</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'42'</span><span style=\"color:#E1E4E8\">);                  </span><span style=\"color:#a0aab5\">// 42</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">zNum</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">).success;        </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">zNum</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'   '</span><span style=\"color:#E1E4E8\">).success;     </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">zNum</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'abc'</span><span style=\"color:#E1E4E8\">).success;     </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"with-default%3A-znumwithdefault()\" data-line=\"199\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#with-default%3A-znumwithdefault()\" aria-hidden=\"true\"></a> with default: <code>zNumWithDefault()</code></h2>\n<p data-line=\"201\" class=\"code-line\">Applies default to missing <code>undefined</code> and empty URL string <code>\"\"</code>. Whitespace-only strings reject as bad input.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"203\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> schema</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> zNumWithDefault</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">20</span><span style=\"color:#E1E4E8\">, z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">));</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">);             </span><span style=\"color:#a0aab5\">// 20</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">);                    </span><span style=\"color:#a0aab5\">// 20</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'3'</span><span style=\"color:#E1E4E8\">);                   </span><span style=\"color:#a0aab5\">// 3</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'   '</span><span style=\"color:#E1E4E8\">).success;     </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"optional%3A-znumoptional()\" data-line=\"212\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#optional%3A-znumoptional()\" aria-hidden=\"true\"></a> optional: <code>zNumOptional()</code></h2>\n<p data-line=\"214\" class=\"code-line\">Normalizes <code>undefined</code>, <code>null</code>, and empty string to <code>undefined</code>. Converts present values to number.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"216\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> schema</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> zNumOptional</span><span style=\"color:#E1E4E8\">(z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">);             </span><span style=\"color:#a0aab5\">// undefined</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">null</span><span style=\"color:#E1E4E8\">);                  </span><span style=\"color:#a0aab5\">// undefined</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">);                    </span><span style=\"color:#a0aab5\">// undefined</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'7'</span><span style=\"color:#E1E4E8\">);                   </span><span style=\"color:#a0aab5\">// 7</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'   '</span><span style=\"color:#E1E4E8\">).success;     </span><span style=\"color:#a0aab5\">// false</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"nullable%3A-znumnullable()\" data-line=\"226\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#nullable%3A-znumnullable()\" aria-hidden=\"true\"></a> nullable: <code>zNumNullable()</code></h2>\n<p data-line=\"228\" class=\"code-line\">For JSON body fields where <code>null</code> itself has meaning. Keeps <code>null</code>; maps <code>undefined</code> and empty string to <code>undefined</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"230\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> schema</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> zNumNullable</span><span style=\"color:#E1E4E8\">(z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">null</span><span style=\"color:#E1E4E8\">);                  </span><span style=\"color:#a0aab5\">// null</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">);             </span><span style=\"color:#a0aab5\">// undefined</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">);                    </span><span style=\"color:#a0aab5\">// undefined</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">schema.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'9'</span><span style=\"color:#E1E4E8\">);                   </span><span style=\"color:#a0aab5\">// 9</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"239\" class=\"code-line\">Side by side:</p>\n<table data-line=\"241\" class=\"code-line\">\n<thead data-line=\"241\" class=\"code-line\">\n<tr data-line=\"241\" class=\"code-line\">\n<th>input</th>\n<th style=\"text-align:right\"><code>zNum()</code></th>\n<th style=\"text-align:right\"><code>zNumWithDefault(1)</code></th>\n<th style=\"text-align:right\"><code>zNumOptional()</code></th>\n<th style=\"text-align:right\"><code>zNumNullable()</code></th>\n</tr>\n</thead>\n<tbody data-line=\"243\" class=\"code-line\">\n<tr data-line=\"243\" class=\"code-line\">\n<td><code>\"42\"</code></td>\n<td style=\"text-align:right\">42</td>\n<td style=\"text-align:right\">42</td>\n<td style=\"text-align:right\">42</td>\n<td style=\"text-align:right\">42</td>\n</tr>\n<tr data-line=\"244\" class=\"code-line\">\n<td><code>undefined</code></td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">1</td>\n<td style=\"text-align:right\">undefined</td>\n<td style=\"text-align:right\">undefined</td>\n</tr>\n<tr data-line=\"245\" class=\"code-line\">\n<td><code>\"\"</code></td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">1</td>\n<td style=\"text-align:right\">undefined</td>\n<td style=\"text-align:right\">undefined</td>\n</tr>\n<tr data-line=\"246\" class=\"code-line\">\n<td><code>\"   \"</code></td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">reject</td>\n</tr>\n<tr data-line=\"247\" class=\"code-line\">\n<td><code>null</code></td>\n<td style=\"text-align:right\">0</td>\n<td style=\"text-align:right\">0</td>\n<td style=\"text-align:right\">undefined</td>\n<td style=\"text-align:right\">null</td>\n</tr>\n<tr data-line=\"248\" class=\"code-line\">\n<td><code>\"abc\"</code></td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">reject</td>\n<td style=\"text-align:right\">reject</td>\n</tr>\n</tbody>\n</table>\n<p data-line=\"250\" class=\"code-line\"><code>null</code> becoming <code>0</code> in <code>zNum()</code> and <code>zNumWithDefault()</code> is from <code>Number(null)</code> inside — same as source <code>toNumber</code>. Use <code>zNumNullable()</code> when <code>null</code> must remain.</p>\n<h2 id=\"integrate-into-schemas\" data-line=\"252\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#integrate-into-schemas\" aria-hidden=\"true\"></a> Integrate into schemas</h2>\n<p data-line=\"254\" class=\"code-line\">Helpers return Zod schemas and combine with ordinary fields:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"256\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNum,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNumNullable,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNumOptional,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  zNumWithDefault,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@rdlabo/workers-hono-kit'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { z } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'zod'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> listQuery</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  groupId: </span><span style=\"color:#B392F0\">zNum</span><span style=\"color:#E1E4E8\">(z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">positive</span><span style=\"color:#E1E4E8\">()),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  page: </span><span style=\"color:#B392F0\">zNumWithDefault</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">, z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">)),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  year: </span><span style=\"color:#B392F0\">zNumOptional</span><span style=\"color:#E1E4E8\">(z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1900</span><span style=\"color:#E1E4E8\">)),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  parentId: </span><span style=\"color:#B392F0\">zNumNullable</span><span style=\"color:#E1E4E8\">(z.</span><span style=\"color:#B392F0\">number</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">int</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">positive</span><span style=\"color:#E1E4E8\">()),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">listQuery.</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">({ groupId: </span><span style=\"color:#9ECBFF\">'42'</span><span style=\"color:#E1E4E8\"> });</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">//   groupId: 42,</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">//   page: 1,</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">//   year: undefined,</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">//   parentId: undefined,</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// }</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"281\" class=\"code-line\">After shaping, field-specific constraints like <code>int()</code>, <code>positive()</code>, and <code>min()</code> apply.</p>\n<h2 id=\"non-numeric-%40transform()-also-moves-into-schemas\" data-line=\"283\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#non-numeric-%40transform()-also-moves-into-schemas\" aria-hidden=\"true\"></a> Non-numeric <code>@Transform()</code> also moves into schemas</h2>\n<p data-line=\"285\" class=\"code-line\">Migration shaping was not numbers only. Conversions below are domain-specific; I kept them near schemas, not generic helpers.</p>\n<h2 id=\"map-unexpected-values-to-a-default\" data-line=\"287\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#map-unexpected-values-to-a-default\" aria-hidden=\"true\"></a> Map unexpected values to a default</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"289\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> validity</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">preprocess</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    value </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'expired'</span><span style=\"color:#F97583\"> ?</span><span style=\"color:#9ECBFF\"> 'expired'</span><span style=\"color:#F97583\"> :</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'valid'</span><span style=\"color:#F97583\"> ?</span><span style=\"color:#9ECBFF\"> 'valid'</span><span style=\"color:#F97583\"> :</span><span style=\"color:#9ECBFF\"> 'all'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  z.</span><span style=\"color:#B392F0\">enum</span><span style=\"color:#E1E4E8\">([</span><span style=\"color:#9ECBFF\">'valid'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'expired'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'all'</span><span style=\"color:#E1E4E8\">]),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"297\" class=\"code-line\">Not plain enum validation — it maps anything other than <code>expired</code> and <code>valid</code> to <code>all</code>, reproducing source <code>@Transform()</code>.</p>\n<h2 id=\"limit-boolean-expressions-in-query\" data-line=\"299\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#limit-boolean-expressions-in-query\" aria-hidden=\"true\"></a> Limit boolean expressions in query</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"301\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> excludeDuplicates</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">preprocess</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    value </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> true</span><span style=\"color:#F97583\"> ||</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'true'</span><span style=\"color:#F97583\"> ||</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> '1'</span><span style=\"color:#F97583\"> ||</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  z.</span><span style=\"color:#B392F0\">boolean</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"309\" class=\"code-line\"><code>z.coerce.boolean()</code> uses JavaScript <code>Boolean()</code>, so string <code>\"false\"</code> is truthy and becomes <code>true</code>. When I want a fixed set of accepted forms, the API contract goes into preprocessing.</p>\n<h2 id=\"trim-strings-before-validation\" data-line=\"311\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#trim-strings-before-validation\" aria-hidden=\"true\"></a> Trim strings before validation</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"313\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> searchQuery</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  q: z.</span><span style=\"color:#B392F0\">preprocess</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    (</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">typeof</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'string'</span><span style=\"color:#F97583\"> ?</span><span style=\"color:#E1E4E8\"> value.</span><span style=\"color:#B392F0\">trim</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">:</span><span style=\"color:#E1E4E8\"> value),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    z.</span><span style=\"color:#B392F0\">string</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">min</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  ),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"322\" class=\"code-line\">If only strings arrive, <code>z.string().trim().min(1)</code> alone works. In migration I check existing input types and processing order, and prefer standard Zod API where it fits.</p>\n<h2 id=\"normalize-single-values-to-arrays\" data-line=\"324\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#normalize-single-values-to-arrays\" aria-hidden=\"true\"></a> Normalize single values to arrays</h2>\n<p data-line=\"326\" class=\"code-line\">Where one query parameter is a string and several become an array, I normalize to array before validation:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"328\"><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> sha256Query</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  sha256: z.</span><span style=\"color:#B392F0\">preprocess</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    (</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      Array.</span><span style=\"color:#B392F0\">isArray</span><span style=\"color:#E1E4E8\">(value) </span><span style=\"color:#F97583\">?</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">:</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#F97583\"> ?</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#F97583\"> :</span><span style=\"color:#E1E4E8\"> [value],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    z.</span><span style=\"color:#B392F0\">array</span><span style=\"color:#E1E4E8\">(z.</span><span style=\"color:#B392F0\">string</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">regex</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">/</span><span style=\"color:#F97583\">^</span><span style=\"color:#79B8FF\">[a-f0-9]</span><span style=\"color:#F97583\">{64}$</span><span style=\"color:#9ECBFF\">/</span><span style=\"color:#E1E4E8\">)).</span><span style=\"color:#B392F0\">nonempty</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  ),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"338\" class=\"code-line\">Elsewhere, fields accepting <code>null</code> but aligning downstream to <code>undefined</code> use <code>.nullish().transform((value) =&gt; value ?? undefined)</code>.</p>\n<p data-line=\"340\" class=\"code-line\">So it is less \"I made more Zod helpers\" and more: four numeric variants as shared helpers; other shaping stays as domain Zod schemas in each app.</p>\n<h2 id=\"pin-conversion-results-with-table-tests\" data-line=\"342\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#pin-conversion-results-with-table-tests\" aria-hidden=\"true\"></a> Pin conversion results with table tests</h2>\n<p data-line=\"344\" class=\"code-line\">Value conversion cannot be verified by types alone. Pin success, failure, and shaped values per boundary in tests.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"346\"><span class=\"line\"><span style=\"color:#B392F0\">describe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'zNumOptional'</span><span style=\"color:#E1E4E8\">, () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  it</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'normalizes values equivalent to omitted input to undefined'</span><span style=\"color:#E1E4E8\">, () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    expect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">zNumOptional</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">)).</span><span style=\"color:#B392F0\">toBeUndefined</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    expect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">zNumOptional</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">null</span><span style=\"color:#E1E4E8\">)).</span><span style=\"color:#B392F0\">toBeUndefined</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    expect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">zNumOptional</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">)).</span><span style=\"color:#B392F0\">toBeUndefined</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  it</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'converts numeric strings to numbers and rejects whitespace'</span><span style=\"color:#E1E4E8\">, () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    expect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">zNumOptional</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">parse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'7'</span><span style=\"color:#E1E4E8\">)).</span><span style=\"color:#B392F0\">toBe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">7</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    expect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">zNumOptional</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">safeParse</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'   '</span><span style=\"color:#E1E4E8\">).success).</span><span style=\"color:#B392F0\">toBe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"361\" class=\"code-line\">At minimum I verify:</p>\n<ul data-line=\"363\" class=\"code-line\">\n<li data-line=\"363\" class=\"code-line\">numeric strings</li>\n<li data-line=\"364\" class=\"code-line\"><code>undefined</code></li>\n<li data-line=\"365\" class=\"code-line\">empty string</li>\n<li data-line=\"366\" class=\"code-line\">whitespace-only string</li>\n<li data-line=\"367\" class=\"code-line\"><code>null</code></li>\n<li data-line=\"368\" class=\"code-line\">non-numeric strings</li>\n<li data-line=\"369\" class=\"code-line\">decimals passed to <code>int()</code></li>\n<li data-line=\"370\" class=\"code-line\">whether default satisfies downstream constraints</li>\n</ul>\n<p data-line=\"372\" class=\"code-line\">What I pin is not universally correct conversion but the per-field contract from input to shaped value that existing clients depend on.</p>\n<h2 id=\"summary\" data-line=\"374\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"376\" class=\"code-line\">Moving NestJS to Hono + Zod, TypeScript types and validation constraints alone did not reproduce class-transformer shaping. Besides numeric conversion: boolean coercion, normalization to defaults, trim, and single-value-to-array also needed porting.</p>\n<p data-line=\"378\" class=\"code-line\">What I needed was not blind coercion from types but reading per-DTO-field conversion rules. I express them near schemas with standard Zod <code>pipe()</code>, <code>transform()</code>, and <code>preprocess()</code>, and split four numeric variants shared across projects into helpers.</p>\n<p data-line=\"380\" class=\"code-line\">Port not types but what input becomes after shaping. On Hono + Zod migration, pinning that boundary in tests mattered.</p>\n<p data-line=\"382\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"port-value-conversion%2C-not-types","text":"Port value conversion, not types","level":2},{"id":"typescript-types-do-not-change-values-at-runtime","text":"TypeScript types do not change values at runtime","level":2},{"id":"nestjs-used-%40transform()-for-shaping","text":"NestJS used @Transform() for shaping","level":2},{"id":"first-ask-whether-standard-zod-is-enough","text":"First ask whether standard Zod is enough","level":2},{"id":"for-required-string-input%2C-pipe()-is-enough","text":"For required string input, pipe() is enough","level":2},{"id":"existing-contracts-needed-preprocessing-for-empty-values","text":"Existing contracts needed preprocessing for empty values","level":2},{"id":"introducing-the-shared-library","text":"Introducing the shared library","level":2},{"id":"decide-coercion-per-field%2C-not-uniformly","text":"Decide coercion per field, not uniformly","level":2},{"id":"fields-that-had-%40transform()","text":"Fields that had @Transform()","level":2},{"id":"fields-without-%40transform()","text":"Fields without @Transform()","level":2},{"id":"four-numeric-helpers","text":"Four numeric helpers","level":2},{"id":"required%3A-znum()","text":"required: zNum()","level":2},{"id":"with-default%3A-znumwithdefault()","text":"with default: zNumWithDefault()","level":2},{"id":"optional%3A-znumoptional()","text":"optional: zNumOptional()","level":2},{"id":"nullable%3A-znumnullable()","text":"nullable: zNumNullable()","level":2},{"id":"integrate-into-schemas","text":"Integrate into schemas","level":2},{"id":"non-numeric-%40transform()-also-moves-into-schemas","text":"Non-numeric @Transform() also moves into schemas","level":2},{"id":"map-unexpected-values-to-a-default","text":"Map unexpected values to a default","level":2},{"id":"limit-boolean-expressions-in-query","text":"Limit boolean expressions in query","level":2},{"id":"trim-strings-before-validation","text":"Trim strings before validation","level":2},{"id":"normalize-single-values-to-arrays","text":"Normalize single values to arrays","level":2},{"id":"pin-conversion-results-with-table-tests","text":"Pin conversion results with table tests","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
